; Enemy shot spawn
; $5b00-$5b7f

; Every 8th tick, gives one enemy a shot one row below it. The enemy must be on the screen, in the right half for $60 positive, in the left half for $60 negative. The row must be below 10 and not the row of another shot. Sets $61 bit 2. Enemies: X = 4-1, state $57+x, row $47+x, map column $4b+x.
enemy_shot_spawn
        lda wave_flags
        and #$01
        beq enemy_shot_spawn_done
        lda SPENA                       ; No enemy sprite 1-4 is on.
        and #$1e
        beq enemy_shot_spawn_done
        lda tick
        and #$07
        bne enemy_shot_spawn_done
        ldx #$04
enemy_shot_spawn_loop
        lda enemy_state,x
        beq enemy_shot_spawn_next
        cmp #$d0                        ; Only an enemy with a state $01-$cf.
        bcs enemy_shot_spawn_next
        lda enemy_col,x                 ; Screen column = map column - $0d.
        sec
        sbc map_column
        sta calc_x
        cmp #$28
        bcs enemy_shot_spawn_next
        lda wave_dir
        bmi enemy_shot_spawn_left_half
        lda calc_x
        cmp #$14
        bcc enemy_shot_spawn_next
        bcs enemy_shot_spawn_row
enemy_shot_spawn_left_half
        lda calc_x
        cmp #$14
        bcs enemy_shot_spawn_next
        nop                             ; NOP fill.
        nop
        nop
        nop
        nop
enemy_shot_spawn_row
        nop                             ; NOP fill.
        nop
        nop
        nop
        nop
        lda enemy_row,x
        sta calc_y
        inc calc_y                      ; Shot row = enemy row + 1.
        lda calc_y
        cmp #$0a
        bcs enemy_shot_spawn_next
        cmp enemy_shot_row
        beq enemy_shot_spawn_next
        cmp $3d
        beq enemy_shot_spawn_next
        cmp $3e
        beq enemy_shot_spawn_next
        cmp $3f
        beq enemy_shot_spawn_next
        ldx #$04                        ; Finds a free slot: column negative.
enemy_shot_spawn_find_slot
        lda $3f,x
        bpl enemy_shot_spawn_next_slot
        lda calc_x
        sta $3f,x
        lda calc_y
        sta $3b,x
        lda wave_flags
        ora #$04
        sta wave_flags
        bne enemy_shot_spawn_done
enemy_shot_spawn_next_slot
        dex
        bne enemy_shot_spawn_find_slot
; not executed $5b79-$5b7a
        beq enemy_shot_spawn_done
enemy_shot_spawn_next
        dex
        bne enemy_shot_spawn_loop
        nop
enemy_shot_spawn_done
        rts
